addpath('euler');
addpath('transfer_function');

clear;
clc;
close all;

%hi

%Run euler model
[time, euler_position] = euler_sim(); %[output:95587283]

%Run transfer function
[~, tf_position] = tf_model(time);

% plotting euler model vs transfer function position values
fig1 = figure('Units', 'inches', 'Position', [1 1 8 4.5]); %[output:2af06caf]
plot(time, euler_position, 'b-', 'LineWidth', 1.5); %[output:2af06caf]
hold on; %[output:2af06caf]
plot(time, tf_position, 'r--', 'LineWidth', 1.5); %[output:2af06caf]

xlabel('Time (s)'); %[output:2af06caf]
ylabel('Position (m)'); %[output:2af06caf]
title('Euler Model vs. Transfer Function'); %[output:2af06caf]

legend('Euler Model', 'Transfer Function', 'Location', 'best'); %[output:2af06caf]

grid on; %[output:2af06caf]
hold off; %[output:2af06caf]

% error calculation and documentation
euler_position = euler_position(:);
tf_position = tf_position(:);
error_values = abs(euler_position - tf_position);
max_error = max(error_values);
fprintf('Maximum error: %.6f m/n', max_error); %[output:560f0efe]

% error plotting
fig2 = figure('Units', 'inches', 'Position', [1 1 8 4.5]); %[output:9dc3542c]
plot(time, error_values, 'LineWidth', 1.5); %[output:9dc3542c]
xlabel('Time (s)'); %[output:9dc3542c]
ylabel('Absolute Position Error (m)'); %[output:9dc3542c]
title('Euler vs. Transfer Function Error'); %[output:9dc3542c]
grid on; %[output:9dc3542c]
%[output:2af06caf] %[output:9dc3542c]

